// MemcacheClient is a memcache client that gets its server list from SRV
// records, and periodically updates that ServerList.
type MemcacheClient struct {
	client     *memcache.Client
	serverList *memcache.ServerList
	expiration int32
	hostname   string
	service    string

	quit chan struct{}
	wait sync.WaitGroup
}

