+// isSymlinkTargetDir return true if f's symbolic link target
+// is a directory
+func isSymlinkTargetDir(f os.FileInfo) bool {
+	target, err := os.Readlink(f.Name())
+	if err != nil {
+		return false
+	}
+	targetInfo, err := os.Lstat(target)
+	if err != nil {
+		return false
+	}
+	return targetInfo.IsDir()
+}

