func (f *glintStep) Done() {
	f.mu.Lock()
	defer f.mu.Unlock()

	if f.done {
		return
	}

	// Set done
	f.done = true

	// Set status
	if f.statusVal == "" {
		f.status.reset()
		f.status.Step(StatusOK, f.msg)
	}

	// Unset the waitgroup
	f.wg.Done()
}

