func (p *Propagate) Dispatch() error {
	process := true
	var received int
	log.Lvl4(p.ServerIdentity(), "Starting dispatch as root:", p.IsRoot())
	defer p.Done()
	defer func() {
		if p.IsRoot() {
			if p.onDoneCb != nil {
				p.onDoneCb(received + 1)
			}
		}
	}()

	var gotSendData bool
	var errs []error
	subtreeCount := p.TreeNode().SubtreeCount()

	for process {
		p.Lock()
		timeout := p.sd.Timeout
		log.Lvl4("Got timeout", timeout, "from SendData")
		p.Unlock()
		select {
		case msg := <-p.ChannelSD:
			if gotSendData {
				log.Error("already got msg")
				continue
			}
			gotSendData = true
			log.Lvl3(p.ServerIdentity(), "Got data from",
				msg.ServerIdentity, "and setting timeout to", msg.Timeout)
			p.sd.Timeout = msg.Timeout
			if p.onData != nil {
				_, netMsg, err := network.Unmarshal(msg.Data, p.Suite())
				if err != nil {
					log.Lvlf2("Unmarshal failed with %v", err)
				} else {
					err := p.onData(netMsg)
					if err != nil {
						log.Lvlf2("Propagation callback failed: %v", err)
@@ -200,7 +200,7 @@ <—— This hunk needs review
