						cc.Expect(Some, w[1][0], extWorkload, ExpectWithPorts(4321), ExpectWithSrcIPs(felixes[1].IP))
						cc.CheckConnectivity()
					})
				})

				AfterEach(func() {
					extWorkload.Stop()
				})
			})
