	for k, members := range appBox {
		if len(members) > 1 {
			// create the compound (parent) node for the member nodes
			nodeId := nodeHash(k)
			nd := NodeData{
				Id:        nodeId,
				NodeType:  graph.NodeTypeApp,
				Namespace: members[0].Namespace,
				App:       members[0].App,
