	if err != nil {
		return "", errors.Wrap(err, "lookup change id (new)")
	}
	fmt.Fprintln(buf, "Max change_log ID (next DB):", changeMax)

	if len(issues) > 0 {
		fmt.Fprintln(buf, "\nPotential Problems Found:")
		for _, s := range issues {
			fmt.Fprintln(buf, "- "+s)
		}
	} else {
