func (c *Variable) Latest(ctx context.Context) (Snapshot, error) {
	var haveGood bool
	select {
	case <-c.haveGood:
		haveGood = true
	case <-ctx.Done():
		// We don't return ctx.Err().
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if haveGood && c.lastErr != ErrClosed {
		return c.lastGood, nil
	}
	return Snapshot{}, c.lastErr
}

