func NewOCS(b []byte) *Transaction {
	dw := &Transaction{}
	err := protobuf.DecodeWithConstructors(b, dw, network.DefaultConstructors(cothority.Suite))
	if err != nil {
		log.Error(err)
		return nil
	}
	return dw
}

