func (fs *KBFSOpsStandard) AddFavorite(ctx context.Context,
	fav Favorite) error {
	kbpki := fs.config.KBPKI()
	_, _, err := kbpki.GetCurrentUserInfo(ctx)
	isLoggedIn := err == nil

	if isLoggedIn {
		err := fs.favs.Add(ctx, favToAdd{Favorite: fav, created: false})
		if err != nil {
			return err
		}
	}

	return nil
