+func rosterEqual(r1, r2 *onet.Roster) bool {
+	if len(r1.List) != len(r2.List) {
+		return false
+	}
+	for _, p := range r2.List {
+		found := false
+		for _, d := range r1.List {
+			if p.Equal(d) {
+				found = true
+			}
+		}
+		if !found {
+			return false
+		}
+	}
+	return true
+}

