}

// NewSimulation creates a new NTree-simulation
func NewSimulation(config string) (sda.Simulation, error) {
	es := &Simulation{Checking: 2}
	_, err := toml.Decode(config, es)
	if err != nil {
		return nil, err
	}
	return es, nil
}

